CREATE OR REPLACE FUNCTION public.edit_application_by_token(p_token text,p_applicant jsonb,p_answers jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.applications%ROWTYPE; v public.applicants%ROWTYPE; BEGIN IF length(p_token) NOT BETWEEN 16 AND 200 OR jsonb_typeof(p_applicant)<>'object' OR jsonb_typeof(p_answers)<>'object' OR octet_length(p_answers::text)>250000 THEN RAISE EXCEPTION 'Invalid edit'; END IF; SELECT * INTO a FROM public.applications WHERE edit_token::text=p_token AND edit_token_expires_at>now() FOR UPDATE; IF a.id IS NULL THEN RAISE EXCEPTION 'Edit link unavailable'; END IF; SELECT * INTO v FROM public.applicants WHERE id=a.applicant_id FOR UPDATE; IF length(coalesce(p_applicant->>'first_name','')) NOT BETWEEN 1 AND 100 OR length(coalesce(p_applicant->>'last_name','')) NOT BETWEEN 1 AND 100 OR length(coalesce(p_applicant->>'email','')) NOT BETWEEN 3 AND 255 OR length(coalesce(p_applicant->>'phone',''))>40 OR length(coalesce(p_applicant->>'photo_url',''))>2000 THEN RAISE EXCEPTION 'Invalid applicant details'; END IF; INSERT INTO public.application_revisions(application_id,revision_number,previous_answers,previous_applicant_data,changed_by) VALUES(a.id,(SELECT coalesce(max(revision_number),0)+1 FROM public.application_revisions WHERE application_id=a.id),a.answers,jsonb_build_object('first_name',v.first_name,'last_name',v.last_name,'email',v.email,'phone',v.phone,'home_zip',v.home_zip,'photo_url',v.photo_url),'applicant'); UPDATE public.applicants SET first_name=p_applicant->>'first_name',last_name=p_applicant->>'last_name',email=p_applicant->>'email',phone=p_applicant->>'phone',home_zip=nullif(p_applicant->>'home_zip',''),photo_url=nullif(p_applicant->>'photo_url','') WHERE id=a.applicant_id; UPDATE public.applications SET answers=p_answers,status='updated',edit_token=null,edit_token_expires_at=null,missing_fields='[]'::jsonb,admin_message=null WHERE id=a.id; RETURN jsonb_build_object('ok',true); END $$; REVOKE ALL ON FUNCTION public.edit_application_by_token(text,jsonb,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.edit_application_by_token(text,jsonb,jsonb) TO service_role;